from pathlib import Path

resolver_path = Path('src/services/sec/secDebtResolver.ts')
test_path = Path('src/services/sec/secDebtResolver.test.ts')
resolver = resolver_path.read_text()

old_doc = """ * 3. A reconciled long-term debt family when `LongTermDebtCurrent + LongTermDebtNoncurrent`\n *    exactly reconciles to `LongTermDebt` for the same instant. If same-period `CommercialPaper` is\n *    separately reported, it is added once; stale historical commercial-paper facts are never carried forward.\n *    A same-period `ShortTermBorrowings` fact or finance-lease liability keeps the family fail-closed because\n *    it could make the borrowing-only total incomplete or overlapping.\n *\n * Missing facts are never converted to zero, stale debt is never carried into a newer balance sheet, and\n * overlapping aliases are never summed. If a current-period family is internally inconsistent, total debt stays null.\n"""
new_doc = """ * 3. A reconciled `LongTermDebt` aggregate. US-GAAP `LongTermDebt` is itself the aggregate\n *    carrying amount including current and noncurrent long-term debt and may include commercial paper, so\n *    `CommercialPaper` is never blindly added on top. When components are available, the aggregate must\n *    reconcile either to `LongTermDebtCurrent + LongTermDebtNoncurrent` or to those components plus a\n *    same-period separately tagged `CommercialPaper` fact. A same-period `ShortTermBorrowings` fact or\n *    finance-lease liability keeps this borrowing-only family fail-closed.\n *\n * Missing facts are never converted to zero, stale debt is never carried into a newer balance sheet, and\n * overlapping aliases are never summed. If a current-period family is internally inconsistent, total debt stays null.\n"""
if old_doc not in resolver:
    raise SystemExit('Phase 3R doc anchor not found')
resolver = resolver.replace(old_doc, new_doc, 1)

old = """    const reconciledLongTermDebt = ltCurrent\n      && ltNoncurrent\n      && ltAggregate\n      && finite(ltCurrent.value)\n      && finite(ltNoncurrent.value)\n      && finite(ltAggregate.value)\n      && samePeriodEnd(ltCurrent, ltNoncurrent, ltAggregate)\n      && approximatelyEqual(ltCurrent.value + ltNoncurrent.value, ltAggregate.value);\n\n    const familyEnd = ltAggregate?.end;\n    const samePeriodShortTerm = Boolean(\n      familyEnd\n      && overlappingShortTerm\n      && finite(overlappingShortTerm.value)\n      && overlappingShortTerm.end === familyEnd\n    );\n    const samePeriodLease = Boolean(\n      familyEnd\n      && ((separateLeaseCurrent && finite(separateLeaseCurrent.value) && separateLeaseCurrent.end === familyEnd)\n        || (separateLeaseNoncurrent && finite(separateLeaseNoncurrent.value) && separateLeaseNoncurrent.end === familyEnd))\n    );\n    const samePeriodPaper = Boolean(\n      reconciledLongTermDebt\n      && ltAggregate\n      && paper\n      && finite(paper.value)\n      && samePeriodEnd(ltCurrent, ltNoncurrent, ltAggregate, paper)\n    );\n    const mismatchedPaperForFiscalQuarter = Boolean(\n      reconciledLongTermDebt\n      && paper\n      && finite(paper.value)\n      && ltAggregate\n      && paper.end !== ltAggregate.end\n    );\n\n    // A reconciled current/non-current long-term debt family is already a complete authoritative\n    // long-term borrowing amount for the instant. Commercial paper is added only when SEC reports\n    // it for that exact same instant. Historical paper is not carried forward and is not treated as zero.\n    if (\n      reconciledLongTermDebt\n      && ltAggregate\n      && ltCurrent\n      && ltNoncurrent\n      && !samePeriodShortTerm\n      && !samePeriodLease\n      && !mismatchedPaperForFiscalQuarter\n    ) {\n      const paperFact = samePeriodPaper && paper ? paper : undefined;\n      const accessions = Array.from(new Set([\n        ...ltCurrent.accessionNumbers,\n        ...ltNoncurrent.accessionNumbers,\n        ...ltAggregate.accessionNumbers,\n        ...(paperFact?.accessionNumbers ?? []),\n      ]));\n      const totalValue = ltAggregate.value + (paperFact?.value ?? 0);\n      const paperNote = paperFact\n        ? ` + separately reported us-gaap:${RECONCILED_COMMERCIAL_PAPER_FAMILY.commercialPaper}`\n        : '';\n      const absenceNote = paperFact\n        ? 'CommercialPaper was reported for the same instant and added exactly once.'\n        : 'No CommercialPaper fact was reported for this fiscal-quarter instant; no stale short-term debt was carried forward.';\n      return {\n        metric: 'total_debt',\n        statement: 'balance_sheet',\n        value: round(totalValue / 1_000_000),\n        unit: 'USD_M',\n        period,\n        periodEnd: ltAggregate.end,\n        type: 'derived',\n        verification: 'verified',\n        source: sourceForFact(bundle, ltAggregate, RECONCILED_COMMERCIAL_PAPER_FAMILY.longTermAggregate),\n        derivation: `Deterministic SEC total debt = reconciled us-gaap:${RECONCILED_COMMERCIAL_PAPER_FAMILY.longTermAggregate}${paperNote}. LongTermDebt was verified to equal LongTermDebtCurrent + LongTermDebtNoncurrent for the same instant; accessions: ${accessions.join(', ')}. ${absenceNote} No same-period ShortTermBorrowings or finance-lease liability fact was present.`,\n      };\n    }\n"""

new = """    const familyEnd = ltAggregate?.end;\n    const componentsShareInstant = Boolean(\n      ltCurrent\n      && ltNoncurrent\n      && ltAggregate\n      && finite(ltCurrent.value)\n      && finite(ltNoncurrent.value)\n      && finite(ltAggregate.value)\n      && samePeriodEnd(ltCurrent, ltNoncurrent, ltAggregate)\n    );\n    const samePeriodPaper = Boolean(\n      componentsShareInstant\n      && paper\n      && finite(paper.value)\n      && samePeriodEnd(ltCurrent, ltNoncurrent, ltAggregate, paper)\n    );\n    const componentTotal = componentsShareInstant && ltCurrent && ltNoncurrent\n      ? ltCurrent.value + ltNoncurrent.value\n      : null;\n    const reconcilesWithoutSeparatePaper = Boolean(\n      componentTotal !== null\n      && ltAggregate\n      && approximatelyEqual(componentTotal, ltAggregate.value)\n    );\n    const reconcilesWithSeparatePaper = Boolean(\n      componentTotal !== null\n      && samePeriodPaper\n      && paper\n      && ltAggregate\n      && approximatelyEqual(componentTotal + paper.value, ltAggregate.value)\n    );\n    const aggregateReconciled = reconcilesWithoutSeparatePaper || reconcilesWithSeparatePaper;\n\n    const samePeriodShortTerm = Boolean(\n      familyEnd\n      && overlappingShortTerm\n      && finite(overlappingShortTerm.value)\n      && overlappingShortTerm.end === familyEnd\n    );\n    const samePeriodLease = Boolean(\n      familyEnd\n      && ((separateLeaseCurrent && finite(separateLeaseCurrent.value) && separateLeaseCurrent.end === familyEnd)\n        || (separateLeaseNoncurrent && finite(separateLeaseNoncurrent.value) && separateLeaseNoncurrent.end === familyEnd))\n    );\n    const nearCurrentPaperMismatch = Boolean(\n      familyEnd\n      && paper\n      && finite(paper.value)\n      && paper.end !== familyEnd\n      && Number.isFinite(Date.parse(paper.end))\n      && Number.isFinite(Date.parse(familyEnd))\n      && Math.abs(Date.parse(paper.end) - Date.parse(familyEnd)) <= 120 * 86_400_000\n    );\n\n    // LongTermDebt is the authoritative aggregate and can already contain commercial paper.\n    // CommercialPaper is therefore used only to prove reconciliation, never added on top of the aggregate.\n    if (\n      aggregateReconciled\n      && ltAggregate\n      && ltCurrent\n      && ltNoncurrent\n      && !samePeriodShortTerm\n      && !samePeriodLease\n      && !nearCurrentPaperMismatch\n    ) {\n      const paperFact = samePeriodPaper && paper ? paper : undefined;\n      const accessions = Array.from(new Set([\n        ...ltCurrent.accessionNumbers,\n        ...ltNoncurrent.accessionNumbers,\n        ...ltAggregate.accessionNumbers,\n        ...(paperFact?.accessionNumbers ?? []),\n      ]));\n      const reconciliationNote = reconcilesWithSeparatePaper\n        ? `LongTermDebt reconciled to LongTermDebtCurrent + LongTermDebtNoncurrent + separately tagged us-gaap:${RECONCILED_COMMERCIAL_PAPER_FAMILY.commercialPaper}. CommercialPaper was not added again.`\n        : `LongTermDebt reconciled to LongTermDebtCurrent + LongTermDebtNoncurrent. Any separately tagged CommercialPaper was not added again because the aggregate is authoritative.`;\n      return {\n        metric: 'total_debt',\n        statement: 'balance_sheet',\n        value: round(ltAggregate.value / 1_000_000),\n        unit: 'USD_M',\n        period,\n        periodEnd: ltAggregate.end,\n        type: 'derived',\n        verification: 'verified',\n        source: sourceForFact(bundle, ltAggregate, RECONCILED_COMMERCIAL_PAPER_FAMILY.longTermAggregate),\n        derivation: `Deterministic SEC total debt = reconciled us-gaap:${RECONCILED_COMMERCIAL_PAPER_FAMILY.longTermAggregate}. ${reconciliationNote} Accessions: ${accessions.join(', ')}. Stale debt facts were not carried forward; no same-period ShortTermBorrowings or finance-lease liability fact was present.`,\n      };\n    }\n"""
if old not in resolver:
    raise SystemExit('Phase 3R resolver anchor not found')
resolver = resolver.replace(old, new, 1)
resolver_path.write_text(resolver)

tests = test_path.read_text()

# Generic commercial-paper family: aggregate already equals components + separately tagged paper.
tests = tests.replace(
"""    LongTermDebt: unit(four([100_000_000, 100_000_000, 100_000_000, 100_000_000], 'lta')),\n    CommercialPaper: unit(four([5_000_000, 6_000_000, 7_000_000, 8_000_000], 'cp')),\n  }));\n  const total = resolved.values['balance_sheet.total_debt'];\n  assert.deepEqual(total.map(item => item.value), [105, 106, 107, 108]);\n  assert.ok(total.every(item => item.verification === 'verified'));\n  assert.match(total[3].derivation || '', /reconciled us-gaap:LongTermDebt \\+ separately reported us-gaap:CommercialPaper/);\n  assert.match(total[3].derivation || '', /LongTermDebtCurrent \\+ LongTermDebtNoncurrent/);\n""",
"""    LongTermDebt: unit(four([105_000_000, 106_000_000, 107_000_000, 108_000_000], 'lta')),\n    CommercialPaper: unit(four([5_000_000, 6_000_000, 7_000_000, 8_000_000], 'cp')),\n  }));\n  const total = resolved.values['balance_sheet.total_debt'];\n  assert.deepEqual(total.map(item => item.value), [105, 106, 107, 108]);\n  assert.ok(total.every(item => item.verification === 'verified'));\n  assert.match(total[3].derivation || '', /LongTermDebtCurrent \\+ LongTermDebtNoncurrent \\+ separately tagged us-gaap:CommercialPaper/);\n  assert.match(total[3].derivation || '', /CommercialPaper was not added again/);\n""",
1)

# A one-day paper instant mismatch stays fail-closed even if the aggregate otherwise reconciles.
# Existing test already expresses this invariant and remains unchanged.

old_aapl = """  // AAPL-like shape: current + non-current term debt reconcile to the aggregate and\n  // same-period commercial paper is a separate current liability, so it is added once.\n  const resolved = attachVerifiedTotalDebtFromSec(baseDataset(), bundle({\n    LongTermDebtCurrent: unit(four([11_000_000_000, 11_100_000_000, 11_007_000_000, 11_007_000_000], 'aapl-ltc')),\n    LongTermDebtNoncurrent: unit(four([75_000_000_000, 73_000_000_000, 71_340_000_000, 71_340_000_000], 'aapl-ltnc')),\n    LongTermDebt: unit(four([86_000_000_000, 84_100_000_000, 82_347_000_000, 82_347_000_000], 'aapl-lta')),\n    CommercialPaper: unit(four([4_000_000_000, 3_000_000_000, 1_997_000_000, 1_997_000_000], 'aapl-cp')),\n    // A stale prior-year lease fact must not poison the current-period borrowing family.\n    FinanceLeaseLiabilityCurrent: unit([fact(2025, 'FY', 1_000_000_000, 'stale-lease')]),\n  }));\n  const total = resolved.values['balance_sheet.total_debt'];\n  assert.equal(total[3].value, 84344);\n  assert.equal(total[3].verification, 'verified');\n  assert.match(total[3].derivation || '', /CommercialPaper was reported for the same instant and added exactly once/);\n"""
new_aapl = """  // AAPL-like shape: LongTermDebt is the aggregate and reconciles to current + non-current\n  // term debt + separately tagged commercial paper. The aggregate must be used once, not CP added twice.\n  const resolved = attachVerifiedTotalDebtFromSec(baseDataset(), bundle({\n    LongTermDebtCurrent: unit(four([11_000_000_000, 11_100_000_000, 11_007_000_000, 11_007_000_000], 'aapl-ltc')),\n    LongTermDebtNoncurrent: unit(four([75_000_000_000, 73_000_000_000, 71_340_000_000, 71_340_000_000], 'aapl-ltnc')),\n    LongTermDebt: unit(four([90_000_000_000, 87_100_000_000, 84_344_000_000, 84_344_000_000], 'aapl-lta')),\n    CommercialPaper: unit(four([4_000_000_000, 3_000_000_000, 1_997_000_000, 1_997_000_000], 'aapl-cp')),\n    // A stale prior-year lease fact must not poison the current-period borrowing family.\n    FinanceLeaseLiabilityCurrent: unit([fact(2025, 'FY', 1_000_000_000, 'stale-lease')]),\n  }));\n  const total = resolved.values['balance_sheet.total_debt'];\n  assert.equal(total[3].value, 84344);\n  assert.equal(total[3].verification, 'verified');\n  assert.match(total[3].derivation || '', /CommercialPaper was not added again/);\n"""
if old_aapl not in tests:
    raise SystemExit('Phase 3R AAPL test anchor not found')
tests = tests.replace(old_aapl, new_aapl, 1)

# Add an explicit anti-double-count test where CP is separately tagged but the LongTermDebt aggregate
# already reconciles to current + noncurrent. We trust the aggregate and do not add CP a second time.
anchor = "\n{\n  const resolved = attachVerifiedTotalDebtFromSec(baseDataset(), bundle({\n    LongTermDebtCurrent: unit(four([10_000_000, 11_000_000, 12_000_000, 13_000_000], 'ltc')),\n    LongTermDebtNoncurrent: unit(four([90_000_000, 89_000_000, 88_000_000, 87_000_000], 'ltnc')),\n    LongTermDebt: unit(four([100_000_000, 100_000_000, 100_000_000, 100_000_000], 'lta')),\n    CommercialPaper: unit(four([5_000_000, 6_000_000, 7_000_000, 8_000_000], 'cp')),\n    ShortTermBorrowings: unit([fact(2026, 'FY', 9_000_000, 'a4')]),\n"
anti = """
{
  const resolved = attachVerifiedTotalDebtFromSec(baseDataset(), bundle({
    LongTermDebtCurrent: unit(four([10_000_000, 11_000_000, 12_000_000, 13_000_000], 'ltc-nodouble')),
    LongTermDebtNoncurrent: unit(four([90_000_000, 89_000_000, 88_000_000, 87_000_000], 'ltnc-nodouble')),
    LongTermDebt: unit(four([100_000_000, 100_000_000, 100_000_000, 100_000_000], 'lta-nodouble')),
    CommercialPaper: unit(four([5_000_000, 6_000_000, 7_000_000, 8_000_000], 'cp-nodouble')),
  }));
  const total = resolved.values['balance_sheet.total_debt'];
  assert.deepEqual(total.map(item => item.value), [100, 100, 100, 100]);
  assert.match(total[3].derivation || '', /CommercialPaper was not added again/);
}

"""
if anchor not in tests:
    raise SystemExit('Phase 3R anti-double-count insertion anchor not found')
tests = tests.replace(anchor, anti + anchor, 1)

test_path.write_text(tests)
